'use strict';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d');
const W=1200,H=510,GRAVITY=160;let terrain=[],tanks=[],turn=0,round=1,wind=0,shot=null,particles=[],trails=[],busy=false,ended=false,heavy=false,aiTimer=null,epoch=0,sound=false,audio;
const controls=['angle','power','normal','heavy','fire','left','right'];
function tone(f,d=.12){if(!sound)return;try{audio??=new AudioContext();let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=f;g.gain.setValueAtTime(.06,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.start();o.stop(audio.currentTime+d);}catch{}}
function yAt(x){return terrain[Math.max(0,Math.min(W-1,Math.round(x)))];}
function newWind(){wind=Math.round((Math.random()*2-1)*24);}
function start(){clearTimeout(aiTimer);epoch++;terrain=Array.from({length:W},(_,x)=>340+38*Math.sin(x*.006)+20*Math.sin(x*.017+1)+9*Math.cos(x*.032));tanks=[{x:170,hp:1000,fuel:100,stock:3,angle:45,power:60},{x:1030,hp:1000,fuel:100,stock:3,angle:135,power:60}];turn=0;round=1;busy=false;ended=false;shot=null;trails=[];particles=[];heavy=false;newWind();$('result').hidden=true;$('mapname').textContent=$('map').value==='desert'?'노을 사막':'초록빛 군도';$('name1').textContent='오렌지 폭스'+($('mode').value==='ai'?' · CPU':'');toast('각도와 파워를 조절한 뒤 발사하세요!');sync();}
function toast(s){$('toast').textContent=s;}
function isCPU(){return turn===1&&$('mode').value==='ai';}
function sync(){const t=tanks[turn];$('angle').value=t.angle;$('power').value=t.power;$('angleVal').textContent=t.angle+'°';$('powerVal').textContent=t.power+'%';$('round').textContent='ROUND '+String(round).padStart(2,'0');$('turn').textContent=(turn===0?'블루':'오렌지')+'의 차례';$('wind').textContent='바람 '+(wind>=0?'→ ':'← ')+Math.abs(wind);$('fuel').textContent='연료 '+t.fuel+'%';$('stock').textContent=t.stock;$('normal').classList.toggle('selected',!heavy);$('heavy').classList.toggle('selected',heavy);for(let i=0;i<2;i++){$('hp'+i).textContent=tanks[i].hp.toLocaleString()+' HP';$('bar'+i).style.width=tanks[i].hp/10+'%';}for(const id of controls)$(id).disabled=busy||ended||isCPU();$('heavy').disabled||=t.stock<=0;}
function muzzle(t,angle=t.angle){let a=angle*Math.PI/180;return{x:t.x+Math.cos(a)*30,y:yAt(t.x)-18-Math.sin(a)*30};}
function launch(){if(busy||ended)return;let t=tanks[turn];if(heavy&&t.stock<=0)return;if(heavy)t.stock--;const m=muzzle(t),a=t.angle*Math.PI/180,v=100+t.power*4.3;shot={...m,vx:Math.cos(a)*v,vy:-Math.sin(a)*v,heavy,age:0};busy=true;trails=[];tone(120,.22);toast('포탄 비행 중…');sync();}
function explode(x,y,special){let radius=special?68:49;shot=null;let damage=[];for(let i=0;i<2;i++){let d=Math.hypot(tanks[i].x-x,yAt(tanks[i].x)-14-y);let hit=Math.max(0,Math.round((1-d/(radius*1.9))*(special?410:310)));tanks[i].hp=Math.max(0,tanks[i].hp-hit);if(hit)damage.push((i?'오렌지':'블루')+' −'+hit+' HP');}for(let xx=Math.max(0,Math.floor(x-radius));xx<Math.min(W,x+radius);xx++){let bottom=y+Math.sqrt(Math.max(0,radius*radius-(xx-x)**2))*.7;terrain[xx]=Math.min(H-32,Math.max(terrain[xx],bottom));}for(let i=0;i<38;i++)particles.push({x,y,vx:(Math.random()-.5)*220,vy:-Math.random()*190,life:1,color:i%2?'#ffca72':'#fff0a9'});tone(55,.35);toast(damage.length?damage.join(' / '):'아슬아슬! 다음 한 발을 노려보세요.');sync();const token=epoch;aiTimer=setTimeout(()=>{if(token===epoch)finishTurn();},1250);}
function finishTurn(){if(tanks.some(t=>t.hp<=0)){ended=true;busy=false;$('result').hidden=false;$('winner').textContent=tanks.every(t=>t.hp<=0)?'무승부!':(tanks[0].hp>0?'블루 코멧':'오렌지 폭스')+' 승리!';sync();return;}turn=1-turn;if(turn===0)round++;tanks[turn].fuel=100;newWind();heavy=false;busy=false;sync();toast(isCPU()?'오렌지 폭스가 조준 중입니다…':(turn?'오렌지':'블루')+'의 차례입니다.');if(isCPU()){let token=epoch;aiTimer=setTimeout(()=>{if(token!==epoch)return;aimCPU();launch();},1100);}}
function predict(t,a,p){let pos=muzzle(t,a),v=100+p*4.3,vx=Math.cos(a*Math.PI/180)*v,vy=-Math.sin(a*Math.PI/180)*v;for(let s=0;s<900;s++){vx+=wind*.025;vy+=GRAVITY*.025;pos.x+=vx*.025;pos.y+=vy*.025;if(pos.x<0||pos.x>W)return pos.x;if(pos.y>=yAt(pos.x))return pos.x;}return pos.x;}
function aimCPU(){let t=tanks[1],best={score:Infinity};for(let a=98;a<173;a+=2)for(let p=18;p<=100;p+=2){let score=Math.abs(predict(t,a,p)-tanks[0].x);if(score<best.score)best={score,a,p};}t.angle=best.a;t.power=Math.max(15,Math.min(100,best.p+Math.round((Math.random()-.5)*5)));heavy=t.stock>0&&Math.random()<.35;sync();}
function move(dir){if(busy||ended||isCPU())return;let t=tanks[turn];if(t.fuel<10)return;let target=Math.max(35,Math.min(W-35,t.x+dir*12));if(Math.abs(target-tanks[1-turn].x)<48)return;t.x=target;t.fuel-=10;sync();}
for(const id of ['angle','power'])$(id).oninput=()=>{if(busy||ended||isCPU())return;tanks[turn][id]=+$(id).value;sync();};$('fire').onclick=()=>{if(!isCPU())launch();};$('normal').onclick=()=>{heavy=false;sync();};$('heavy').onclick=()=>{heavy=true;sync();};$('left').onclick=()=>move(-1);$('right').onclick=()=>move(1);for(const id of ['restart','again'])$(id).onclick=start;$('mode').onchange=start;$('map').onchange=start;$('help').onclick=()=>$('guide').showModal();$('closeGuide').onclick=()=>$('guide').close();$('sound').onclick=()=>{sound=!sound;$('sound').textContent='사운드 '+(sound?'ON':'OFF');tone(440);};document.addEventListener('keydown',e=>{if($('guide').open||/INPUT|SELECT|BUTTON/.test(document.activeElement.tagName))return;if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code))e.preventDefault();if(busy||ended||isCPU())return;if(e.code==='Space')launch();if(e.code==='ArrowLeft')move(-1);if(e.code==='ArrowRight')move(1);if(e.code==='ArrowUp'||e.code==='ArrowDown'){tanks[turn].angle=Math.max(5,Math.min(175,tanks[turn].angle+(e.code==='ArrowUp'?1:-1)));sync();}});
function cloud(x,y,s){ctx.fillStyle='#ffffff90';ctx.beginPath();ctx.ellipse(x,y,42*s,10*s,0,0,Math.PI*2);ctx.ellipse(x-14*s,y-8*s,18*s,15*s,0,0,Math.PI*2);ctx.ellipse(x+10*s,y-12*s,23*s,19*s,0,0,Math.PI*2);ctx.fill();}
function tank(t,i){let x=t.x,y=yAt(x)-12;ctx.save();ctx.translate(x,y);let slope=Math.atan2(yAt(x+12)-yAt(x-12),24);ctx.rotate(slope*.6);ctx.fillStyle='#254d4b';ctx.beginPath();ctx.roundRect(-23,1,46,15,8);ctx.fill();for(let a=-15;a<=15;a+=10){ctx.fillStyle='#91aba0';ctx.beginPath();ctx.arc(a,8,4,0,7);ctx.fill();ctx.fillStyle='#36595b';ctx.beginPath();ctx.arc(a,8,2,0,7);ctx.fill();}ctx.fillStyle=i?'#ed965b':'#56aacc';ctx.beginPath();ctx.roundRect(-21,-7,42,15,5);ctx.fill();ctx.fillStyle=i?'#ffb878':'#7dcce1';ctx.beginPath();ctx.roundRect(-12,-17,26,15,6);ctx.fill();ctx.restore();let m=muzzle(t);ctx.strokeStyle=i?'#b96b42':'#35798e';ctx.lineWidth=8;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x,y-8);ctx.lineTo(m.x,m.y);ctx.stroke();ctx.fillStyle='#ffffff';ctx.beginPath();ctx.arc(x-3,y-9,3,0,7);ctx.fill();if(turn===i&&!ended){ctx.fillStyle=i?'#d5864b':'#428fae';ctx.beginPath();ctx.moveTo(x-6,y-47);ctx.lineTo(x+6,y-47);ctx.lineTo(x,y-39);ctx.fill();}ctx.fillStyle='#2a5549';ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.fillText(i?'ORANGE FOX':'BLUE COMET',x,y+33);}
function draw(){let desert=$('map').value==='desert';let gradient=ctx.createLinearGradient(0,0,0,H);gradient.addColorStop(0,desert?'#f6d8bd':'#d5ebe7');gradient.addColorStop(1,desert?'#f8ebcf':'#f0f5df');ctx.fillStyle=gradient;ctx.fillRect(0,0,W,H);ctx.fillStyle=desert?'#fff0bb':'#fbf5d0';ctx.beginPath();ctx.arc(922,90,40,0,7);ctx.fill();cloud(230,90,1);cloud(610,63,.75);cloud(1050,156,.8);for(let layer=0;layer<2;layer++){ctx.fillStyle=desert?(layer?'#d5b69a':'#e6c9ac'):(layer?'#a6c7b6':'#c1d8ca');ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<=W;x+=15)ctx.lineTo(x,275+layer*35+Math.sin(x*.009+layer*3)*26+Math.sin(x*.02)*14);ctx.lineTo(W,H);ctx.fill();}ctx.fillStyle=desert?'#b38b61':'#779573';ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<W;x++)ctx.lineTo(x,terrain[x]);ctx.lineTo(W,H);ctx.fill();ctx.save();ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<W;x++)ctx.lineTo(x,terrain[x]+13);ctx.lineTo(W,H);ctx.clip();ctx.fillStyle=desert?'#ccaa7d':'#a8b38b';ctx.fillRect(0,0,W,H);ctx.fillStyle=desert?'#a18059':'#8f9c76';for(let x=0;x<W;x+=29)for(let y=355;y<H;y+=29){ctx.beginPath();ctx.ellipse(x+(y%3)*7,y,3,1.5,0,0,7);ctx.fill();}ctx.restore();ctx.strokeStyle=desert?'#e5c58b':'#5e8a60';ctx.lineWidth=8;ctx.beginPath();for(let x=0;x<W;x++){if(!x)ctx.moveTo(x,terrain[x]);else ctx.lineTo(x,terrain[x]);}ctx.stroke();if(!desert){for(let x=32;x<W;x+=67){let y=yAt(x);ctx.strokeStyle='#618c5d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-3,y-9);ctx.moveTo(x,y);ctx.lineTo(x+5,y-7);ctx.stroke();}}tanks.forEach(tank);if(!busy&&!ended){let t=tanks[turn],m=muzzle(t),a=t.angle*Math.PI/180;ctx.fillStyle='#ffffffbb';for(let n=1;n<7;n++){ctx.beginPath();ctx.arc(m.x+Math.cos(a)*n*12,m.y-Math.sin(a)*n*12,2,0,7);ctx.fill();}}ctx.strokeStyle='#ffffff99';ctx.lineWidth=2;ctx.beginPath();trails.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();if(shot){ctx.fillStyle=shot.heavy?'#ffce63':'#fff9c9';ctx.shadowColor='#ffdc85';ctx.shadowBlur=12;ctx.beginPath();ctx.arc(shot.x,shot.y,shot.heavy?6:4,0,7);ctx.fill();ctx.shadowBlur=0;}for(const p of particles){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,3+3*p.life,0,7);ctx.fill();}ctx.globalAlpha=1;}
let last=0;function frame(now){let dt=Math.min((now-last)/1000||.016,.04);last=now;if(shot){for(let s=0;s<4&&shot;s++){let p=shot,step=dt/4;p.vx+=wind*step;p.vy+=GRAVITY*step;p.x+=p.vx*step;p.y+=p.vy*step;p.age+=step;if(p.x<0||p.x>=W||p.age>16){shot=null;toast('포탄이 전장을 벗어났습니다.');let token=epoch;aiTimer=setTimeout(()=>{if(token===epoch)finishTurn();},700);}else if(p.y>=yAt(p.x))explode(p.x,p.y,p.heavy);else{let target=tanks.find((t,i)=>i!==turn&&Math.hypot(t.x-p.x,yAt(t.x)-14-p.y)<22);if(target)explode(p.x,p.y,p.heavy);}}if(shot){trails.push({x:shot.x,y:shot.y});if(trails.length>100)trails.shift();}}for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=220*dt;p.life-=dt*1.7;}particles=particles.filter(p=>p.life>0);draw();requestAnimationFrame(frame);}start();requestAnimationFrame(frame);
